/* Local simulation only. No network calls or external execution. */
(function(root){
  const Pay=typeof module!=='undefined'?require('./nunnpay.js'):root.NunnPayHandoff;
  const catalog=[['Apples','6 crisp apples',5.49,'🍎'],['Oat milk','64 fl oz · original',4.79,'🥛'],['Sourdough','1 fresh loaf',6.50,'🍞'],['Eggs','12 large · free range',5.99,'🥚'],['Baby spinach','5 oz · washed',3.99,'🥬'],['Pasta','16 oz · rigatoni',2.49,'🍝']];
  const money=n=>Math.round(n*100)/100;
  function create(){return {id:'SIM-'+Date.now().toString(36).toUpperCase(),state:'draft',budget:85,request:'',items:catalog.map((r,i)=>({id:i,name:r[0],detail:r[1],price:r[2],icon:r[3],qty:1})),revision:1,approval:null,dispatched:false,events:[]};}
  function total(t){return money(t.items.reduce((a,i)=>a+i.price*i.qty,0)+8+5);}
  function event(t,label){t.events.push({at:new Date().toISOString(),label});}
  function prepare(t,request,budget){if(!request.trim())throw Error('Tell DIRKS what you need first.');if(!Number.isFinite(budget)||budget<=0||budget>10000)throw Error('Enter a budget between $0.01 and $10,000.');t.request=request.trim();t.budget=budget;t.state='review';t.approval=null;t.payment=Pay.prepare(t,total(t));event(t,'Prepared simulated basket and NunnPay handoff; user review required.');}
  function edit(t,id,delta){if(!['review','approved'].includes(t.state))throw Error('Start or prepare a task before editing.');const item=t.items.find(i=>i.id===id);if(!item)throw Error('Unknown item.');item.qty=Math.max(0,Math.min(9,item.qty+delta));t.revision++;t.approval=null;t.state='review';t.payment=Pay.prepare(t,total(t));event(t,'Basket changed; basket and payment approvals invalidated.');}
  function approve(t){if(t.state!=='review')throw Error('This task is not awaiting approval.');if(!t.items.some(i=>i.qty>0))throw Error('Add at least one item.');if(total(t)>t.budget)throw Error('Basket exceeds your budget. Adjust items or start with a larger budget.');Pay.approve(t,total(t));t.approval={revision:t.revision,total:total(t),at:new Date().toISOString()};t.state='approved';event(t,'Exact basket, demo recipient and NunnPay amount approved in simulation.');}
  function dispatch(t,outcome,paymentOutcome='pending'){if(t.state!=='approved'||!t.approval||t.approval.revision!==t.revision||t.approval.total!==total(t)||total(t)>t.budget)throw Error('A current approval within budget is required.');if(t.dispatched)throw Error('Already submitted. Reconcile status before another attempt.');if(!['confirmed','timeout','failed'].includes(outcome))throw Error('Unknown simulated outcome.');Pay.submit(t,total(t),paymentOutcome);t.dispatched=true;t.state=outcome==='timeout'?'unresolved':outcome==='failed'?'failed':'confirmed';event(t,'Simulated submission dispatched once.');event(t,'NunnPay simulation: '+t.payment.status+'. No funds moved.');event(t,t.state==='confirmed'?'Mock provider confirmed order; payment tracked separately.':t.state==='failed'?'Mock provider rejected order; no order created.':'Mock provider timed out; order status unknown.');}
  function reconcile(t){if(t.state!=='unresolved')throw Error('Only uncertain outcomes require this status check.');t.state='confirmed';event(t,'Simulated status check found original order; no resubmission.');}
  function cancel(t){if(!['draft','review','approved'].includes(t.state))throw Error('Submission already occurred. This prototype cannot cancel a provider order.');Pay.cancel(t);t.state='cancelled';t.approval=null;event(t,'Stopped before dispatch; nothing submitted.');}
  function reconcilePayment(t){Pay.check(t);event(t,'Mock NunnPay status check confirmed original payment; no resubmission.');}
  const api={create,total,prepare,edit,approve,dispatch,reconcile,reconcilePayment,cancel};if(typeof module!=='undefined')module.exports=api;else root.Dirks=api;
})(typeof window!=='undefined'?window:globalThis);
